fn main() {
    // Source resources are regenerated by the packaging command. Direct cargo
    // builds generate a local payload too, rather than silently omit the host.
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..");
    println!("cargo:rerun-if-changed=gen/host/integrity.json");
    if !std::path::Path::new("gen/host/integrity.json").is_file() {
        assert!(
            std::process::Command::new(if cfg!(windows) { "python" } else { "python3" })
                .arg(root.join("scripts/prepare_client_host.py"))
                .status()
                .expect("Python 3 is required to prepare host resources")
                .success()
        );
    }
    let manifest = tauri_build::AppManifest::new().commands(&[
        "current_server",
        "connect_server",
        "deployment_status",
        "start_deployment",
        "cancel_deployment",
        "accept_deployment_license",
    ]);
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(manifest))
        .expect("Unable to build client capability manifest");
}
